import styled from "styled-components";

const TableContainer = styled.div`
  width: 100%;
  max-width: 800px;
  background: white;
  padding: 20px;
  border-radius: 8px;
  box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
`;

const Th = styled.th`
  background: #007bff;
  color: white;
  padding: 10px;
  text-align: left;
`;

const Td = styled.td`
  border: 1px solid #ddd;
  padding: 10px;
`;

export default FastaTable = ({ sample }) => {
  return (
    <Container>
      <Wrapper>
        <TableContainer>
        <h3>Fasta Sample</h3>
        <Table>
            <thead>
            <tr>
                <Th>Field</Th>
                <Th>Value</Th>
            </tr>
            </thead>
            <tbody>
            <tr>
                <Td>_id</Td>
                <Td>{sample._id}</Td>
            </tr>
            <tr>
                <Td>Name</Td>
                <Td>{sample.name || "N/A"}</Td>
            </tr>
            <tr>
                <Td>Strain</Td>
                <Td>{sample.strain}</Td>
            </tr>
            <tr>
                <Td>Header</Td>
                <Td>{sample.header}</Td>
            </tr>
            <tr>
                <Td>Length</Td>
                <Td>{sample.length}</Td>
            </tr>
            <tr>
                <Td>Status</Td>
                <Td>{sample.status ? "Active" : "Inactive"}</Td>
            </tr>
            <tr>
                <Td>Created At</Td>
                <Td>{new Date(sample.createdAt).toLocaleString()}</Td>
            </tr>
            <tr>
                <Td>Updated At</Td>
                <Td>{new Date(sample.updatedAt).toLocaleString()}</Td>
            </tr>
            </tbody>
        </Table>
        </TableContainer>
      </Wrapper>
    </Container> 
  );
};
